            key,
            MemoEntry {
                _semantic: prop.clone(),
                _structural: structural.cloned(),
                merged: merged.clone(),
                unread: !unread_kinds.is_empty(),
            },
        );
        props.insert(prop.name.clone(), merged);
    }
